export async function logPageView(path: string) {
  await fetch('https://analytics.example.com/api/track', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ event: 'page_view', path }),
  }).catch(() => {})
}

import { after } from 'next/server'
import { logPageView } from '@/lib/analytics'

export default function Home() {
  after(async () => {
    await logPageView('/')
  })

  return (
    <main>
      <h1>Welcome</h1>
      <p>Welcome to our site! We're glad you're here.</p>
    </main>
  )
}

